recipes.code:
{
  "inputs": [
    {
      "id": "impreza-api-key",
      "type": "promptString",
      "description": "Impreza API key (imp_…), from the clientarea → Impreza API.",
      "password": true
    },
    {
      "id": "impreza-api-secret",
      "type": "promptString",
      "description": "Impreza API secret (shown once when the key is created).",
      "password": true
    }
  ],
  "servers": {
    "impreza": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "impreza-mcp@0.4.3"
      ],
      "env": {
        "IMPREZA_API_KEY": "${input:impreza-api-key}",
        "IMPREZA_API_SECRET": "${input:impreza-api-secret}",
        "IMPREZA_BASE_URL": "<impreza-base-url>"
      }
    }
  }
}
